#include <MacErrors.h>#endif// ANSI#ifndef __STDIO__#include <StdIO.h>#endif//========================================================================================// GLOBAL Functions//========================================================================================#undef Inherited//----------------------------------------------------------------------------------------// GetQuickTimeVersion_AC://----------------------------------------------------------------------------------------long GetQuickTimeVersion_AC(){	static bool defined;	static long version;	if (!defined)	{		defined = true;		OSErr err = Gestalt(gestaltQuickTimeVersion, &version);#if qProjectBuilder		(void) err;#endif	}	return version;}//----------------------------------------------------------------------------------------// CloseIfMovieFile_AC//----------------------------------------------------------------------------------------#pragma	segment	AResshort CloseIfMovieFile_AC(short resRefNum){	if (resRefNum != kNoFileRefNum_AC)	{		CloseMovieFile(resRefNum);		resRefNum = kNoFileRefNum_AC;	}	return resRefNum;}//----------------------------------------------------------------------------------------// DisposeIfMovie_AC//----------------------------------------------------------------------------------------#pragma	segment	AResMovie DisposeIfMovie_AC(Movie movie){	if (movie)	{		DisposeMovie(movie);		ThrowIfMoviesError_AC();		movie = NULL;	}	return movie;}//----------------------------------------------------------------------------------------// GetPoster_AC//----------------------------------------------------------------------------------------#pragma	segment	ANonResPicHandle GetPoster_AC(Movie movie){	// get the movie poster and its frame	PicHandle picHandle = GetMoviePosterPict(movie);	CRect_AC picFrame = (*picHandle)->picFrame;	//	if the picture frame is empty, return a NULL handle	if (picHandle && picFrame.Empty())		picHandle = reinterpret_cast<PicHandle>(DisposeIfHandle_AC(reinterpret_cast<Handle>(picHandle)));	return picHandle;}#if qDebugExceptions//----------------------------------------------------------------------------------------// DebugThrowIfMoviesError_AC//----------------------------------------------------------------------------------------void DebugThrowIfMoviesError_AC( const char* inFile, short inLine){	OSErr e = GetMoviesError();	if (e != noErr)		DebugThrowError_AC(e, inFile, inLine);}#else//----------------------------------------------------------------------------------------// ThrowIfMoviesError_AC//----------------------------------------------------------------------------------------void ThrowIfMoviesError_AC(){	OSErr e = GetMoviesError();	if (e != noErr)		ThrowError_AC(e);}#endif//========================================================================================// CLASS CMovie_AC//========================================================================================#undef Inherited//----------------------------------------------------------------------------------------// Static creation routines//----------------------------------------------------------------------------------------//----------------------------------------------------------------------------------------// CMovie_AC::NewMovie: //----------------------------------------------------------------------------------------Movie CMovie_AC::NewMovie(){	return NewMovie(0);}//----------------------------------------------------------------------------------------// CMovie_AC::NewMovie: //----------------------------------------------------------------------------------------Movie CMovie_AC::NewMovie(long newMovieFlags){	Movie newMovie = ::NewMovie(newMovieFlags);	ThrowIfMoviesError_AC();#if qCoreDebug	Assertion_AC(newMovie != nil, "I guess we need a ThrowIfMemError_AC too!");#endif	return newMovie;}//--------------